#include <string.h>
#include <stdlib.h>

#include "magick.h"

size_t RegisterJPEGImage(void) {
  static const char
    *jpeg_suffixes[] = {"JPE", "JPEG", "JPG", "JPS", "PJPEG"},
    *jpeg_mime_type[] = {"image/jpeg"},
    *jpeg_version = LIBJPEG_VERSION;

  MagickInfo
    *magick_info;

  register ssize_t i;

  magick_info = (MagickInfo *) AcquireMagickMemory(sizeof(MagickInfo));
  (void) memset(magick_info, 0, sizeof(MagickInfo));
  magick_info->decoder = JPEGDecoder;
  magick_info->encoder = JPEGRewriter;
  magick_info->thread_support = MagickTrue;
  magick_info->is_grayscale = MagickFalse;
  magick_info->is_compressed = MagickTrue;
  magick_info->is_24bit = MagickTrue;
  magick_info->blob_support = MagickTrue;
  magick_info->raw_support = MagickFalse;
  magick_info->adjoin = MagickTrue;
  magick_info->seekable = MagickTrue;
  magick_info->version = (char *) AcquireString(jpeg_version);
  magick_info->mime = (char **) AcquireQuantumMemory(1UL, sizeof(*magick_info->mime));
  magick_info->mime[0] = (char *) AcquireString(jpeg_mime_type[0]);

  for (i = 0; i < (ssize_t) (sizeof(jpeg_suffixes) / sizeof(*jpeg_suffixes)); i++) {
    magick_info->name = (char *) AcquireString(jpeg_suffixes[i]);
    SetMagickInfo(magick_info);
    RegisterMagickInfo(magick_info);
  }

  return strlen(jpeg_version);
}

